// 全球客户数据清洗 V1.1
// 节点：类型清洗
//
// 目标：筛选925银饰、珠宝、饰品相关潜在客户
//
// V1.1升级：
// 同时利用 Google Maps 官方的：
// business_type / type / category / subtypes
//
// 不包含国家规则。
// 将来增加语言时，只扩展关键词配置，不修改主体逻辑。


// ==================================================
// 1. 通用文本处理
// ==================================================

function normalizeText(value) {
  return (value ?? "")
    .toString()
    .normalize("NFKC")
    .toLowerCase()
    .trim()
    .replace(/[.,;:()[\]{}]/g, " ")
    .replace(/[_\-\/]+/g, " ")
    .replace(/\s+/g, " ");
}


function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== null &&
      value !== undefined &&
      value.toString().trim() !== ""
    ) {
      return value;
    }
  }

  return "";
}


// 英文关键词按完整单词或短语判断
// 阿拉伯语等非拉丁文字使用包含判断
function containsTerm(text, term) {
  if (!text || !term) {
    return false;
  }

  const normalizedText = normalizeText(text);
  const normalizedTerm = normalizeText(term);

  const isEnglishTerm = /^[a-z0-9 ]+$/.test(normalizedTerm);

  if (!isEnglishTerm) {
    return normalizedText.includes(normalizedTerm);
  }

  const escaped = normalizedTerm.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );

  const pattern = new RegExp(
    `(^|[^a-z0-9])${escaped}([^a-z0-9]|$)`,
    "i"
  );

  return pattern.test(normalizedText);
}


function matchesAny(text, terms) {
  if (!text) {
    return false;
  }

  return terms.some(term =>
    containsTerm(text, term)
  );
}


// ==================================================
// 2. 读取 Google Maps 行业字段
// ==================================================

// business_type 是我们数据总表里的标准字段
const businessTypeRaw = firstNonEmpty(
  $json.business_type,
  $json.type,
  $json.business?.type
);

const categoryRaw = firstNonEmpty(
  $json.category,
  $json.business?.category
);

const subtypesRaw = firstNonEmpty(
  $json.subtypes,
  $json.business?.subtypes
);


const businessType = normalizeText(businessTypeRaw);
const category = normalizeText(categoryRaw);
const subtypes = normalizeText(subtypesRaw);

const companyName = normalizeText(
  $json.company_name
);


// 把所有 Google Maps 行业信号合并
// 不覆盖任何原字段，只用于行业判断
const industryText = [
  businessType,
  category,
  subtypes
]
  .filter(Boolean)
  .join(" | ");


// 默认状态
$json.industry_match = false;
$json.lead_status = "raw";
$json.reject_reason = "";


// ==================================================
// 3. 判断行业字段是否完全缺失/无效
// ==================================================

const invalidSinglePatterns = [
  /^$/,
  /^fb$/,
  /^facebook$/,
  /^duckduckgo$/,
  /^google$/,
  /^instagram$/,
  /^whatsapp$/,
  /^http:\/\//,
  /^https:\/\//,
  /^www\./
];


function isInvalidIndustryValue(value) {
  const text = normalizeText(value);

  return invalidSinglePatterns.some(pattern =>
    pattern.test(text)
  );
}


const allIndustrySignalsInvalid =
  isInvalidIndustryValue(businessType) &&
  isInvalidIndustryValue(category) &&
  isInvalidIndustryValue(subtypes);


// ==================================================
// 4. 强目标行业
//
// 规则：
// business_type / category / subtypes
// 任意一个出现明确珠宝证据即可进入目标行业。
// ==================================================

const strongTargetTypes = [

  // 珠宝零售
  "jewelry store",
  "jewellery store",
  "jewelry stores",
  "jewellery stores",
  "jewelry shop",
  "jewellery shop",

  "jeweler",
  "jeweller",
  "jewelers",
  "jewellers",

  // B2B
  "jewelry wholesaler",
  "jewellery wholesaler",
  "wholesale jeweler",
  "wholesale jeweller",

  "jewelry supplier",
  "jewellery supplier",

  "jewelry manufacturer",
  "jewellery manufacturer",

  "jewelry distributor",
  "jewellery distributor",

  "jewelry retailer",
  "jewellery retailer",

  // 设计
  "jewelry designer",
  "jewellery designer",

  // 银饰
  "silver jewelry",
  "silver jewellery",
  "silver jewelry store",
  "silver jewellery store",
  "sterling silver",

  // 时尚饰品
  "fashion jewelry",
  "fashion jewellery",

  "costume jewelry",
  "costume jewellery",

  "fashion accessories store",

  // 身体饰品
  "body jewelry store",
  "body jewellery store",
  "body piercing shop",
  "piercing shop",

  // 贵金属/珠宝相关
  "gold dealer",
  "diamond dealer",

  "goldsmith",
  "silversmith",
  "engraver",

  "jewelry repair service",
  "jewellery repair service",

  // 阿拉伯语
  "متجر مجوهرات",
  "محل مجوهرات",
  "مجوهرات",
  "مجوهرات فضية",
  "فضة",
  "ذهب",
  "ألماس",
  "الماس",
  "صائغ",
  "صياغة",
  "إكسسوارات",
  "اكسسوارات"
];


if (matchesAny(industryText, strongTargetTypes)) {

  $json.industry_match = true;
  $json.lead_status = "raw";
  $json.reject_reason = "";

  return $json;
}


// ==================================================
// 5. 硬黑名单行业
//
// 注意：
// 强珠宝证据已经在上一步优先放行。
// 因此“Jewelry store + Gift shop”等不会误杀。
// 只有没有强珠宝证据时才执行黑名单。
// ==================================================

const blacklist = [

  "restaurant",
  "cafe",
  "coffee shop",
  "coffee store",
  "hotel",
  "resort",

  "clinic",
  "hospital",
  "medical center",
  "doctor",
  "dentist",
  "pharmacy",

  "school",
  "university",
  "college",
  "kindergarten",

  "gym",
  "fitness center",

  "bank",
  "insurance",
  "real estate",

  "construction",
  "building materials",
  "steel distributor",
  "mining equipment",

  "car dealer",
  "auto repair",
  "car wash",
  "gas station",

  "plumber",
  "electrician",

  "commercial printer",
  "paper distributor",

  "appliance store",
  "electronics store",
  "mobile phone store",
  "computer store",

  "grocery store",
  "hypermarket",
  "supermarket",
  "discount supermarket",
  "dry fruit store",
  "food store",

  "furniture store",
  "home goods store",

  "travel agency",
  "law firm",
  "accounting firm",
  "logistics company",
  "courier service",
  "warehouse",

  // 阿拉伯语
  "مطعم",
  "مقهى",
  "فندق",
  "منتجع",
  "عيادة",
  "مستشفى",
  "صيدلية",
  "مدرسة",
  "جامعة",
  "نادي رياضي",
  "بنك",
  "تأمين",
  "عقارات",
  "مقاولات",
  "سيارات",
  "إلكترونيات",
  "سوبرماركت",
  "أثاث"
];


if (matchesAny(industryText, blacklist)) {

  $json.industry_match = false;
  $json.lead_status = "rejected";
  $json.reject_reason = "industry_blacklist";

  return $json;
}


// ==================================================
// 6. 辅助目标行业
//
// 没有明确珠宝类型，
// 但这些渠道存在销售银饰的合理可能。
// ==================================================

const supportingTargetTypes = [

  "accessories store",
  "boutique",
  "gift shop",
  "watch store",
  "fashion store",

  "بوتيك",
  "متجر هدايا",
  "محل هدايا",
  "متجر ساعات"
];


if (matchesAny(industryText, supportingTargetTypes)) {

  $json.industry_match = true;
  $json.lead_status = "raw";
  $json.reject_reason = "";

  return $json;
}


// ==================================================
// 7. 公司名称辅助判断
//
// 只有行业字段没有提供明确结论时使用。
// 黑名单已经在上一步处理，因此公司名不能覆盖黑名单。
// ==================================================

const companyTargetKeywords = [

  "jewelry",
  "jewellery",
  "jewel",
  "jewels",
  "jeweler",
  "jeweller",

  "silver",
  "sterling",
  "gold",
  "diamond",
  "gems",
  "gemstone",

  "accessories",
  "bijoux",
  "bijouterie",

  "مجوهرات",
  "فضة",
  "ذهب",
  "ألماس",
  "الماس",
  "إكسسوارات",
  "اكسسوارات"
];


if (matchesAny(companyName, companyTargetKeywords)) {

  $json.industry_match = true;
  $json.lead_status = "raw";
  $json.reject_reason = "";

  return $json;
}


// ==================================================
// 8. 所有行业字段都无效或缺失
// ==================================================

if (allIndustrySignalsInvalid) {

  $json.industry_match = false;
  $json.lead_status = "rejected";
  $json.reject_reason = "invalid_business_type";

  return $json;
}


// ==================================================
// 9. 有行业信息，但没有任何珠宝行业证据
// ==================================================

$json.industry_match = false;
$json.lead_status = "rejected";
$json.reject_reason = "industry_not_matched";

return $json;

// 全球客户数据清洗 V1
// 节点：邮箱清理
//
// 只负责：
// 1. 规范化 email
// 2. 统一 email_status
// 3. 判断 email_valid
//
// 不修改：
// lead_status
// reject_reason
// industry_match
// Email / WhatsApp / CRM历史字段


// ==================================================
// 1. 读取原始字段
// ==================================================

const emailRaw = ($json.email ?? "")
  .toString()
  .trim()
  .toLowerCase();

const originalEmailStatus = (
  $json.email_status ??
  $json["email.emails_validator.status"] ??
  ""
)
  .toString()
  .trim()
  .toUpperCase();


// ==================================================
// 2. 默认输出
// ==================================================

$json.email = emailRaw;
$json.email_status = "UNKNOWN";
$json.email_valid = false;


// ==================================================
// 3. 空邮箱
// 客户仍然保留，可继续通过WhatsApp开发
// ==================================================

if (!emailRaw) {
  $json.email_status = "UNKNOWN";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 4. BLACKLISTED优先处理
// 邮箱禁止发送，但不拒绝整个客户
// ==================================================

if (originalEmailStatus.includes("BLACKLISTED")) {
  $json.email_status = "BLACKLISTED";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 5. 邮箱格式验证
// ==================================================

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(emailRaw)) {
  $json.email_status = "INVALID";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 6. 非邮箱垃圾内容
// ==================================================

const invalidContentPatterns = [
  "facebook",
  "instagram",
  "duckduckgo",
  "google",
  "whatsapp",
  "http://",
  "https://",
  "www."
];

const containsInvalidContent = invalidContentPatterns.some(pattern =>
  emailRaw.includes(pattern)
);

if (containsInvalidContent) {
  $json.email_status = "INVALID";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 7. 占位或测试邮箱
// ==================================================

const placeholderEmails = [
  "xxx@xxx.com",
  "abc@abc.com",
  "test@test.com",
  "example@example.com",
  "email@email.com",
  "name@domain.com",
  "yourname@email.com",
  "info@example.com",
  "sales@example.com",
  "contact@example.com",
  "admin@admin.com"
];

if (placeholderEmails.includes(emailRaw)) {
  $json.email_status = "INVALID";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 8. 拆分邮箱前缀和域名
// ==================================================

const [localPart = "", domainPart = ""] = emailRaw.split("@");


// ==================================================
// 9. 假邮箱前缀
// 只做完全匹配，不误伤包含这些字符的正常邮箱
// ==================================================

const badLocalParts = [
  "xxx",
  "abc",
  "test",
  "example",
  "email",
  "yourname",
  "username",
  "user",
  "demo",
  "sample"
];

if (badLocalParts.includes(localPart)) {
  $json.email_status = "INVALID";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 10. 假邮箱域名
// ==================================================

const badDomains = [
  "xxx.com",
  "abc.com",
  "example.com",
  "domain.com",
  "email.com",
  "test.com",
  "sample.com",
  "demo.com"
];

if (badDomains.includes(domainPart)) {
  $json.email_status = "INVALID";
  $json.email_valid = false;

  return $json;
}


// ==================================================
// 11. 根据邮箱验证状态统一输出
// ==================================================

if (originalEmailStatus.includes("RECEIVING")) {
  $json.email_status = "RECEIVING";
  $json.email_valid = true;

  return $json;
}

if (originalEmailStatus.includes("INVALID")) {
  $json.email_status = "INVALID";
  $json.email_valid = false;

  return $json;
}


// 没有明确验证结果，或原始状态无法识别
$json.email_status = "UNKNOWN";
$json.email_valid = false;

return $json;

// 全球客户数据清洗 V1
// 节点：通用电话清洗
//
// 国家号段规则来自“国家识别与规则配置”节点。
// 未来新增国家时，不需要修改本节点。
//
// 输出：
// phone_clean
// phone_type
// whatsapp_available
// phone_country_mismatch


// ==================================================
// 1. 默认输出
// ==================================================

const phoneRaw = ($json.phone ?? "")
  .toString()
  .trim();

$json.phone_clean = "";
$json.phone_type = "missing";
$json.whatsapp_available = false;

// 临时诊断字段：国家字段与电话号码国家不一致
$json.phone_country_mismatch = false;


// ==================================================
// 2. 空电话
// ==================================================

if (!phoneRaw) {
  return $json;
}


// ==================================================
// 3. 阿拉伯数字、波斯数字转英文数字
// ==================================================

function normalizeDigits(value) {
  const arabicDigits = "٠١٢٣٤٥٦٧٨٩";
  const persianDigits = "۰۱۲۳۴۵۶۷۸۹";

  return (value ?? "")
    .toString()
    .replace(/[٠-٩]/g, digit =>
      arabicDigits.indexOf(digit).toString()
    )
    .replace(/[۰-۹]/g, digit =>
      persianDigits.indexOf(digit).toString()
    );
}


function digitsOnly(value) {
  return normalizeDigits(value)
    .replace(/\D/g, "");
}


// ==================================================
// 4. 经纬度、小数等垃圾值
// ==================================================

const compactRaw = normalizeDigits(phoneRaw)
  .replace(/\s+/g, "");

if (/^[+-]?\d{1,3}[.,]\d+$/.test(compactRaw)) {
  $json.phone_type = "invalid";
  return $json;
}


// ==================================================
// 5. 读取国家配置
// ==================================================

const countrySupported =
  $json.cleaning_country_status === "supported";

const dialCode = digitsOnly(
  $json.cleaning_dial_code
);

const trunkPrefix = digitsOnly(
  $json.cleaning_local_trunk_prefix
);

const phoneRules =
  $json.cleaning_phone_rules &&
  typeof $json.cleaning_phone_rules === "object"
    ? $json.cleaning_phone_rules
    : {};


function compilePatterns(patterns) {
  if (!Array.isArray(patterns)) {
    return [];
  }

  return patterns
    .map(pattern => {
      try {
        return new RegExp(pattern);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
}


const mobilePatterns = compilePatterns(
  phoneRules.mobile_patterns
);

const landlinePatterns = compilePatterns(
  phoneRules.landline_patterns
);

const hotlinePatterns = compilePatterns(
  phoneRules.hotline_patterns
);

const shortNumberPatterns = compilePatterns(
  phoneRules.short_number_patterns
);

const whatsappPhoneTypes = Array.isArray(
  phoneRules.whatsapp_phone_types
)
  ? phoneRules.whatsapp_phone_types
  : [];


// ==================================================
// 6. 提取一个或多个候选号码
// 防止两个号码被直接拼接
// ==================================================

function extractCandidates(rawValue) {
  let text = normalizeDigits(rawValue);

  // 删除分机号码
  text = text.replace(
    /\b(?:ext|extension|x)\s*[:.]?\s*\d+\b/gi,
    ""
  );

  // 电话标签作为分隔符
  text = text.replace(
    /\b(?:tel|telephone|phone|mobile|mob|whatsapp|fax)\s*[:.]?/gi,
    "|"
  );

  text = text.replace(
    /\s+(?:or|and)\s+/gi,
    "|"
  );

  const initialParts = text.split(
    /[\/;,|\n\r]+/
  );

  const candidates = [];

  for (const initialPart of initialParts) {
    // 同一段里出现多个“+”时继续拆开
    const parts = initialPart
      .split(/(?=\+)/)
      .map(value => value.trim())
      .filter(Boolean);

    for (const part of parts) {
      let cleaned = part
        .replace(/\s+/g, "")
        .replace(/-/g, "")
        .replace(/\(/g, "")
        .replace(/\)/g, "")
        .replace(/[^\d+]/g, "");

      if (!cleaned) {
        continue;
      }

      // 00国际格式转成+
      if (cleaned.startsWith("00")) {
        cleaned = "+" + cleaned.slice(2);
      }

      const explicitInternational =
        cleaned.startsWith("+");

      // 只允许开头保留一个+
      if (explicitInternational) {
        cleaned =
          "+" +
          cleaned.slice(1).replace(/\+/g, "");
      } else {
        cleaned = cleaned.replace(/\+/g, "");
      }

      const digits = cleaned.replace(/\D/g, "");

      if (digits.length < 3) {
        continue;
      }

      candidates.push({
        digits,
        explicitInternational
      });
    }
  }

  return candidates;
}


// ==================================================
// 7. 通用规则匹配
// ==================================================

function matchesAny(value, patterns) {
  return patterns.some(pattern =>
    pattern.test(value)
  );
}


function buildNationalPhone(nationalNumber) {
  return "+" + dialCode + nationalNumber;
}


// ==================================================
// 8. 判断单个候选号码
// ==================================================

function classifyCandidate(candidate) {
  const digits = candidate.digits;

  // ----------------------------------------------
  // A. 当前国家已经支持
  // ----------------------------------------------

  if (
    countrySupported &&
    dialCode
  ) {
    let nationalNumber = "";
    let belongsToCurrentCountry = false;

    // +966、00966或966开头
    if (digits.startsWith(dialCode)) {
      nationalNumber = digits.slice(
        dialCode.length
      );

      belongsToCurrentCountry = true;
    }

    // 明确带+，但不是当前国家区号
    else if (candidate.explicitInternational) {
      if (
        digits.length >= 8 &&
        digits.length <= 15
      ) {
        return {
          phone_clean: "+" + digits,
          phone_type: "international",
          mismatch: true,
          priority: 2
        };
      }

      return {
        phone_clean: "",
        phone_type: "invalid",
        mismatch: true,
        priority: 0
      };
    }

    // 当前国家的本地号码
    else {
      nationalNumber = digits;
      belongsToCurrentCountry = true;
    }

    // 去掉本地前缀0
    // 例如050... → 50...
    if (
      trunkPrefix &&
      nationalNumber.startsWith(trunkPrefix) &&
      nationalNumber.length > trunkPrefix.length
    ) {
      nationalNumber = nationalNumber.slice(
        trunkPrefix.length
      );
    }

    // 手机
    if (
      matchesAny(
        nationalNumber,
        mobilePatterns
      )
    ) {
      return {
        phone_clean:
          buildNationalPhone(nationalNumber),

        phone_type: "mobile",
        mismatch: false,
        priority: 5
      };
    }

    // 固话
    if (
      matchesAny(
        nationalNumber,
        landlinePatterns
      )
    ) {
      return {
        phone_clean:
          buildNationalPhone(nationalNumber),

        phone_type: "landline",
        mismatch: false,
        priority: 4
      };
    }

    // 800、600、9200等热线
    if (
      matchesAny(
        nationalNumber,
        hotlinePatterns
      )
    ) {
      return {
        phone_clean:
          buildNationalPhone(nationalNumber),

        phone_type: "hotline",
        mismatch: false,
        priority: 3
      };
    }

    // 3—6位短号码不伪造国际格式
    if (
      matchesAny(
        nationalNumber,
        shortNumberPatterns
      )
    ) {
      return {
        phone_clean: nationalNumber,
        phone_type: "hotline",
        mismatch: false,
        priority: 3
      };
    }

    // 当前国家号码但不符合任何合法规则
    if (belongsToCurrentCountry) {
      return {
        phone_clean: "",
        phone_type: "invalid",
        mismatch: false,
        priority: 0
      };
    }
  }


  // ----------------------------------------------
  // B. 国家尚未配置
  // ----------------------------------------------

  if (
    candidate.explicitInternational &&
    digits.length >= 8 &&
    digits.length <= 15
  ) {
    return {
      phone_clean: "+" + digits,
      phone_type: "international",
      mismatch: false,
      priority: 2
    };
  }

  // 本地号码因国家规则尚未开发，暂不强行判错
  return {
    phone_clean: "",
    phone_type: "unknown",
    mismatch: false,
    priority: 1
  };
}


// ==================================================
// 9. 多号码选择
