  // 分别判断本批次渠道重复
  const emailDuplicate =
    hasUsableEmail &&
    seenEmails.has(email);

  const phoneDuplicate =
    hasUsablePhone &&
    seenPhones.has(phone);

  json.email_is_duplicate = emailDuplicate;
  json.phone_is_duplicate = phoneDuplicate;

  // 邮箱重复，但整条客户仍可能因新手机号而保留
