    isEmptyStatus(json.whatsapp_outreach_status)
  ) {
    json.whatsapp_outreach_status =
      "skipped_duplicate_phone";
  }

  const hasNewEmail =
    hasUsableEmail &&
    !emailDuplicate;

  const hasNewPhone =
    hasUsablePhone &&
    !phoneDuplicate;

  const hasAnyNewChannel =
    hasNewEmail ||
    hasNewPhone;

  // 只要还有一个新渠道，就保留客户
  if (hasAnyNewChannel) {
    json.is_duplicate = false;

    if (hasNewEmail) {
      seenEmails.add(email);
    }

    if (hasNewPhone) {
      seenPhones.add(phone);
    }

    output.push({ json });
    continue;
  }

  // 没有任何新开发渠道，整条记录才拒绝
  json.is_duplicate = true;
  json.lead_status = "rejected";

  if (emailDuplicate && phoneDuplicate) {
