    json.reject_reason =
      "duplicate_email_no_new_phone";
  } else if (phoneDuplicate) {
    json.reject_reason =
      "duplicate_phone_no_new_email";
  } else {
    json.reject_reason =
      "no_new_usable_channel";
  }

  output.push({ json });
}

