function normalizeText(value) {
  if (Array.isArray(value)) {
    value = value.join(" ");
  }

  return (value ?? "")
    .toString()
    .normalize("NFKC")
    .toLowerCase()
    .trim()
    .replace(/[.,;:()[\]{}]/g, " ")
    .replace(/[_\-\/]+/g, " ")
    .replace(/\s+/g, " ");
}


// 英文按完整单词/短语匹配
// 阿拉伯语等非拉丁文字按包含匹配
function containsTerm(text, term) {
  if (!text || !term) {
    return false;
  }

  const normalizedText = normalizeText(text);
  const normalizedTerm = normalizeText(term);

  const isEnglishTerm =
    /^[a-z0-9 ]+$/.test(normalizedTerm);

  if (!isEnglishTerm) {
    return normalizedText.includes(normalizedTerm);
  }

  const escaped = normalizedTerm.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );

  const pattern = new RegExp(
    `(^|[^a-z0-9])${escaped}([^a-z0-9]|$)`,
    "i"
  );

  return pattern.test(normalizedText);
}


function matchesAny(text, terms) {
  if (!text) {
    return false;
  }

  return terms.some(term =>
    containsTerm(text, term)
  );
}


function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== null &&
      value !== undefined &&
      value.toString().trim() !== ""
    ) {
      return value;
    }
  }

  return "";
}


function normalizeWebsite(value) {
  let website = (value ?? "")
    .toString()
    .toLowerCase()
    .trim();

  if (!website) {
    return "";
  }

  website = website
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .split(/[/?#]/)[0]
    .replace(/:\d+$/, "")
    .trim();

  const ignoredDomains = [
    "facebook.com",
    "instagram.com",
    "linkedin.com",
    "tiktok.com",
    "youtube.com",
    "twitter.com",
    "x.com",
    "wa.me",
    "whatsapp.com",
    "google.com"
  ];

  if (
    ignoredDomains.some(domain =>
      website === domain ||
      website.endsWith("." + domain)
    )
  ) {
    return "";
  }

  if (!/^(?:[a-z0-9-]+\.)+[a-z]{2,}$/i.test(website)) {
    return "";
  }

  return website;
}


