// 判断完整词或连续短语，减少部分字符误判
function containsPhrase(text, phrase) {
  if (!text || !phrase) {
    return false;
  }

  if (text === phrase) {
    return true;
  }

  return (
    text.startsWith(phrase + " ") ||
    text.endsWith(" " + phrase) ||
    text.includes(" " + phrase + " ")
  );
}


