  $json.cleaning_local_trunk_prefix =
    profile.local_trunk_prefix;

  $json.cleaning_country_status = "supported";
  $json.cleaning_country_detected_by = detectedBy;

  // 电话清洗规则
  $json.cleaning_phone_rules = {
    mobile_patterns:
      profile.phone_rules.mobile_patterns,

    landline_patterns:
      profile.phone_rules.landline_patterns,

    hotline_patterns:
      profile.phone_rules.hotline_patterns,

    short_number_patterns:
      profile.phone_rules.short_number_patterns,

    whatsapp_phone_types:
      profile.phone_rules.whatsapp_phone_types
  };

} else {
  // 无法确认国家时，保留原始country
  $json.country = originalCountry;

  $json.cleaning_country_key = "";
  $json.cleaning_dial_code = "";
  $json.cleaning_local_trunk_prefix = "";
  $json.cleaning_country_status = "unsupported";
  $json.cleaning_country_detected_by = "";

  $json.cleaning_phone_rules = {
    mobile_patterns: [],
    landline_patterns: [],
    hotline_patterns: [],
    short_number_patterns: [],
    whatsapp_phone_types: []
  };
}

return $json;

// 全球客户数据清洗 V1
// 节点：历史渠道分别去重
// Mode：Run Once for All Items
//
// 输入：
// _dedup_source = history  历史干净客户
// _dedup_source = new      本批新客户
//
// 输出：
// 只输出本批仍然至少有一个新开发渠道的客户
//
// 规则：
// 1. 历史邮箱重复、手机号新：保留，Email跳过
// 2. 历史手机号重复、邮箱新：保留，WhatsApp跳过
// 3. 邮箱和手机号都没有新价值：不输出
// 4. 合并本批次去重结果，不覆盖已有发送状态

const allItems = $input.all();

function normalizeEmail(value) {
  return String(value ?? "")
    .normalize("NFKC")
    .trim()
    .toLowerCase();
}

function normalizePhone(value) {
  return String(value ?? "")
    .replace(/\D/g, "");
}

function toBoolean(value) {
  return (
    value === true ||
    value === 1 ||
    value === "1" ||
    String(value ?? "").toLowerCase() === "true"
  );
}

function isEmptyStatus(value) {
  return String(value ?? "").trim() === "";
}

function isValidEmailKey(value) {
  const email = normalizeEmail(value);

  return (
    email !== "" &&
    email !== "__no_email__" &&
    email.includes("@")
  );
}

function isValidPhoneKey(value) {
  const phone = normalizePhone(value);

  return (
    phone.length >= 8 &&
    phone.length <= 15
  );
}

// ==================================================
// 1. 分离历史数据和本批新数据
// ==================================================

const historyRows = allItems
  .map(item => item.json)
  .filter(row => row._dedup_source === "history");

const newRows = allItems
  .map(item => item.json)
  .filter(row => row._dedup_source === "new");

// ==================================================
// 2. 建立历史邮箱和历史手机号集合
// ==================================================

const historicalEmails = new Set();
const historicalPhones = new Set();

for (const row of historyRows) {
  const email = normalizeEmail(row.email);
  const phone = normalizePhone(
    row.phone_clean || row.phone
  );

  if (isValidEmailKey(email)) {
    historicalEmails.add(email);
  }

  if (isValidPhoneKey(phone)) {
    historicalPhones.add(phone);
  }
}

// ==================================================
// 3. 逐条检查本批新客户
// ==================================================

const output = [];

for (const originalRow of newRows) {
  const json = { ...originalRow };

  const email = normalizeEmail(json.email);
  const phone = normalizePhone(
    json.phone_clean || json.phone
  );

  const emailStatus = String(
    json.email_status ?? ""
  )
    .trim()
    .toUpperCase();

  const phoneType = String(
    json.phone_type ?? ""
  )
    .trim()
    .toLowerCase();

  // Email发送流程只开发可正常接收的邮箱
  const hasUsableEmail =
    isValidEmailKey(email) &&
    (
      emailStatus === "RECEIVING" ||
      (
        emailStatus === "" &&
        toBoolean(json.email_valid)
      )
    );

  // WhatsApp发送流程只开发手机号码
  const hasUsablePhone =
    isValidPhoneKey(phone) &&
    phoneType === "mobile";

  // 当前批次去重节点已经产生的结果
  const batchEmailDuplicate =
    toBoolean(json.email_is_duplicate);

  const batchPhoneDuplicate =
    toBoolean(json.phone_is_duplicate);

  // 与历史干净客户表进行比较
  const historyEmailDuplicate =
    hasUsableEmail &&
    historicalEmails.has(email);

  const historyPhoneDuplicate =
    hasUsablePhone &&
    historicalPhones.has(phone);

  // 本批重复或历史重复，任一成立即为渠道重复
  const emailDuplicate =
    batchEmailDuplicate ||
    historyEmailDuplicate;

  const phoneDuplicate =
    batchPhoneDuplicate ||
    historyPhoneDuplicate;

  json.email_is_duplicate =
    emailDuplicate;

  json.phone_is_duplicate =
    phoneDuplicate;

  // 临时检查字段，后面写入前会被删除
  json._history_email_duplicate =
    historyEmailDuplicate;

  json._history_phone_duplicate =
    historyPhoneDuplicate;

  // 邮箱重复，只关闭Email渠道
  if (
    emailDuplicate &&
    isEmptyStatus(json.email_outreach_status)
  ) {
    json.email_outreach_status =
      "skipped_duplicate_email";
  }

  // 手机号重复，只关闭WhatsApp渠道
  if (
    phoneDuplicate &&
    isEmptyStatus(json.whatsapp_outreach_status)
  ) {
    json.whatsapp_outreach_status =
      "skipped_duplicate_phone";
  }

  // 检查是否还有新的可开发渠道
  const hasNewEmail =
    hasUsableEmail &&
    !emailDuplicate;

  const hasNewPhone =
    hasUsablePhone &&
    !phoneDuplicate;

  const hasAnyNewChannel =
    hasNewEmail ||
    hasNewPhone;

  // 至少有一个新渠道，继续写入干净客户表
  if (hasAnyNewChannel) {
    json.is_duplicate = false;

    if (
      String(json.reject_reason ?? "")
        .startsWith("duplicate_")
    ) {
      json.reject_reason = "";
    }

    output.push({
      json
    });

    continue;
  }

  // 邮箱和手机号都没有新价值时，不输出
  // 这条记录不会写入干净客户表
}

return output;
